#include "test_common.h"
#include "file_management.h"
static BmsStatus_t visitor(const void *record,uint32_t index,void *context){CU_ASSERT_PTR_NOT_NULL(record);CU_ASSERT(index<3U);(*(uint32_t*)context)++;return BMS_STATUS_OK;}
static void test_binary_persistence(void){const char *path="cunit_records.dat";uint32_t src[3]={10,20,30},dst[3]={0},count=0,visited=0;bool exists=false;(void)FileManagementDeleteFile(path);ASSERT_OK(FileManagementWriteRecords(path,src,3U,sizeof(uint32_t)));ASSERT_OK(FileManagementFileExists(path,&exists));CU_ASSERT_TRUE(exists);ASSERT_OK(FileManagementGetRecordCount(path,sizeof(uint32_t),&count));CU_ASSERT_EQUAL(count,3U);count=0;ASSERT_OK(FileManagementReadRecords(path,dst,3U,&count,sizeof(uint32_t)));CU_ASSERT_EQUAL(count,3U);CU_ASSERT_EQUAL(dst[1],20U);ASSERT_OK(FileManagementVisitRecords(path,sizeof(uint32_t),visitor,&visited));CU_ASSERT_EQUAL(visited,3U);ASSERT_OK(FileManagementDeleteFile(path));ASSERT_OK(FileManagementFileExists(path,&exists));CU_ASSERT_FALSE(exists);}
static void test_append_empty_errors(void){const char *path="cunit_append.dat";uint32_t a=1,b=2,count=0;(void)FileManagementDeleteFile(path);ASSERT_OK(FileManagementAppendRecord(path,&a,sizeof a));ASSERT_OK(FileManagementAppendRecord(path,&b,sizeof b));ASSERT_OK(FileManagementGetRecordCount(path,sizeof a,&count));CU_ASSERT_EQUAL(count,2U);ASSERT_STATUS(BMS_STATUS_INVALID_ARGUMENT,FileManagementWriteRecords(NULL,&a,1U,sizeof a));ASSERT_OK(FileManagementDeleteFile(path));}
void RegisterFileManagementTests(void){CU_pSuite s=CU_add_suite("File Management",NULL,NULL);CU_add_test(s,"write read count visit delete",test_binary_persistence);CU_add_test(s,"append and invalid arguments",test_append_empty_errors);}
